import { join } from 'path';
/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  swcMinify: true,
  eslint: {
    // Allow linting during development only
    ignoreDuringBuilds: true,
  },
  // Enable experimental app directory (default in Next 14)
  experimental: {
    appDir: true,
  },
  // Optional: customize webpack to support MDX or other features later
  webpack: (config, { dev, isServer }) => {
    return config;
  },
};
export default nextConfig;

import type { Config } from 'tailwindcss';

export default {
  content: [
    './app/**/*.{js,ts,jsx,tsx}',
    './components/**/*.{js,ts,jsx,tsx}'
  ],
  theme: {
    extend: {
      colors: {
        'chat-bg': '#f8f9fa',
        'sidebar-bg': '#ffffff',
        'border-light': '#e9ecef',
        'text-muted': '#6c757d',
        'primary': '#007bff',
        'success': '#28a745'
      }
    }
  },
  plugins: [],
} satisfies Config;

/** @type {import('postcss-load-config').Config} */
const config = {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

export default config;

@tailwind base;
@tailwind components;
@tailwind utilities;

html,
body {
  padding: 0;
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Oxygen,
    Ubuntu, Cantarell, Fira Sans, Droid Sans, Helvetica Neue, sans-serif;
}

a {
  color: inherit;
  text-decoration: none;
}

* {
  box-sizing: border-box;
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #f1f1f1;
}

::-webkit-scrollbar-thumb {
  background: #c1c1c1;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #a8a8a8;
}

import type { Metadata } from 'next';
import './globals.css';

export const metadata: Metadata = {
  title: 'EaseMize Chat',
  description: 'A modern chat interface inspired by EaseMize',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body className="bg-gray-50 min-h-screen">{children}</body>
    </html>
  );
}

import ChatLayout from '@/components/ChatLayout';

export default function Home() {
  return (
    <main className="flex h-screen w-screen">
      <ChatLayout />
    </main>
  );
}

import MessageList from './MessageList';
import PromptInput from './PromptInput';
import ChatSidebar from './ChatSidebar';

export default function ChatLayout() {
  return (
    <div className="flex h-screen w-screen bg-gray-50">
      <ChatSidebar className="w-64 border-r border-gray-200" />
      <div className="flex-1 flex flex-col overflow-hidden">
        <MessageList className="flex-1 overflow-y-auto p-4" />
        <PromptInput />
      </div>
    </div>
  );
}

import MarkdownRenderer from './MarkdownRenderer';

interface Message {
  id: string;
  content: string;
  role: 'user' | 'assistant';
  createdAt: Date;
}

interface MessageListProps {
  messages: Message[];
}

export default function MessageList({ messages }: MessageListProps) {
  return (
    <div className="space-y-6">
      {messages.map((message) => (
        <div key={message.id} className="flex w-full max-w-[300px]">
          {message.role === 'assistant' && (
            <div className="flex-shrink-0 h-10 w-10 rounded-full bg-blue-500 flex items-center justify-center">
              <svg className="h-5 w-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3-.895 3-2-1.343-2-3-2zm0 10c-1.657 0-3 .895-3 2s1.343 2 3 2 3-.895 3-2-1.343-2-3-2z" />
              </svg>
            </div>
          )}
          <div className="ml-3 w-0 flex-1">
            <div className={`flex items-center space-x-2 ${
              message.role === 'assistant' ? 'justify-start' : 'justify-end'
            } mb-1`}>
              {message.role === 'user' ? (
                <span className="text-xs text-gray-500">You</span>
              ) : (
                <span className="text-xs text-gray-500">Assistant</span>
              )}
              <time className="text-xs text-gray-400">{new Date(message.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</time>
            </div>
            <div className={`flex flex-col ${
              message.role === 'assistant' ? 'items-start' : 'items-end'
            }`}>
              <div className={`rounded-xl px-4 py-2 max-w-[280px] ${
                message.role === 'assistant' 
                  ? 'bg-white shadow-sm' 
                  : 'bg-blue-600 text-white'
              }`}>
                <MarkdownRenderer content={message.content} />
              </div>
            </div>
          </div>
          {message.role === 'user' && (
            <div className="flex-shrink-0 h-10 w-10 rounded-full bg-blue-600 flex items-center justify-center">
              <svg className="h-5 w-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
              </svg>
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

